ALTER TABLE "workspace_membership_orders" DROP CONSTRAINT "workspace_orders_context_check";--> statement-breakpoint
ALTER TABLE "workspace_payment_attempts" DROP CONSTRAINT "workspace_payments_definition_check";--> statement-breakpoint
ALTER TABLE "workspace_payment_events" DROP CONSTRAINT "workspace_events_definition_check";--> statement-breakpoint
ALTER TABLE "workspace_refund_attempts" DROP CONSTRAINT "workspace_refund_attempt_check";--> statement-breakpoint
ALTER TABLE "workspace_refund_completions" DROP CONSTRAINT "workspace_refund_completion_check";--> statement-breakpoint
ALTER TABLE "workspace_membership_orders" ADD CONSTRAINT "workspace_orders_context_check" CHECK ("workspace_membership_orders"."purchase_kind" = 'initial' AND "workspace_membership_orders"."provider" = 'razorpay' AND (("workspace_membership_orders"."provider_mode" = 'test' AND "workspace_membership_orders"."commercial_policy_version" = 'workspace-test-noncommercial-v1') OR ("workspace_membership_orders"."provider_mode" = 'live' AND "workspace_membership_orders"."commercial_policy_version" = 'workspace-live-commercial-v1')) AND "workspace_membership_orders"."quote_hash" ~ '^[a-f0-9]{64}$' AND "workspace_membership_orders"."context_hash" ~ '^[a-f0-9]{64}$' AND "workspace_membership_orders"."request_payload_hash" ~ '^[a-f0-9]{64}$' AND "workspace_membership_orders"."provider_receipt" ~ '^wso[a-f0-9]{32}$' AND length("workspace_membership_orders"."provider_account_id") BETWEEN 1 AND 100 AND "workspace_membership_orders"."version" > 0 AND (("workspace_membership_orders"."coupon_id" IS NULL AND "workspace_membership_orders"."coupon_code" IS NULL AND "workspace_membership_orders"."coupon_snapshot" IS NULL AND "workspace_membership_orders"."discount_paise" = 0) OR ("workspace_membership_orders"."coupon_id" IS NOT NULL AND "workspace_membership_orders"."coupon_code" IS NOT NULL AND "workspace_membership_orders"."coupon_snapshot" IS NOT NULL AND "workspace_membership_orders"."discount_paise" > 0)));--> statement-breakpoint
ALTER TABLE "workspace_payment_attempts" ADD CONSTRAINT "workspace_payments_definition_check" CHECK ("workspace_payment_attempts"."provider_mode" IN ('test','live') AND "workspace_payment_attempts"."provider_payment_id" ~ '^pay_[A-Za-z0-9]{6,80}$' AND "workspace_payment_attempts"."provider_order_id" ~ '^order_[A-Za-z0-9]{6,80}$' AND "workspace_payment_attempts"."amount_paise" > 0 AND "workspace_payment_attempts"."currency" ~ '^[A-Z]{3}$' AND "workspace_payment_attempts"."state" IN ('created','authorized','failed','captured') AND "workspace_payment_attempts"."refunded_paise" BETWEEN 0 AND "workspace_payment_attempts"."amount_paise" AND "workspace_payment_attempts"."evidence_hash" ~ '^[a-f0-9]{64}$' AND ("workspace_payment_attempts"."winner" = false OR "workspace_payment_attempts"."state" = 'captured') AND (("workspace_payment_attempts"."captured_at" IS NULL AND "workspace_payment_attempts"."capture_time_source" IS NULL) OR ("workspace_payment_attempts"."captured_at" IS NOT NULL AND "workspace_payment_attempts"."capture_time_source" IS NOT NULL AND "workspace_payment_attempts"."captured_at" >= "workspace_payment_attempts"."provider_created_at" AND "workspace_payment_attempts"."state" = 'captured' AND ("workspace_payment_attempts"."capture_time_source" = 'razorpay_payment_captured_event_v1' OR ("workspace_payment_attempts"."provider_mode" = 'test' AND "workspace_payment_attempts"."capture_time_source" = 'test_authoritative')))));--> statement-breakpoint
ALTER TABLE "workspace_payment_events" ADD CONSTRAINT "workspace_events_definition_check" CHECK ("workspace_payment_events"."provider_mode" IN ('test','live') AND length("workspace_payment_events"."event_id") BETWEEN 1 AND 100 AND "workspace_payment_events"."event_type" ~ '^[a-z][a-z._]{1,79}$' AND "workspace_payment_events"."payload_hash" ~ '^[a-f0-9]{64}$' AND ("workspace_payment_events"."anomaly_hash" IS NULL OR "workspace_payment_events"."anomaly_hash" ~ '^[a-f0-9]{64}$') AND "workspace_payment_events"."processing_state" IN ('pending','processing','retry','processed','needs_review','ignored') AND "workspace_payment_events"."attempt_count" BETWEEN 0 AND 100 AND (("workspace_payment_events"."processing_state" IN ('processed','ignored','needs_review') AND "workspace_payment_events"."processed_at" IS NOT NULL) OR ("workspace_payment_events"."processing_state" IN ('pending','processing','retry') AND "workspace_payment_events"."processed_at" IS NULL)));--> statement-breakpoint
ALTER TABLE "workspace_refund_attempts" ADD CONSTRAINT "workspace_refund_attempt_check" CHECK ("workspace_refund_attempts"."amount_paise" > 0 AND "workspace_refund_attempts"."currency" = 'INR' AND "workspace_refund_attempts"."provider_mode" IN ('test','live') AND "workspace_refund_attempts"."provider_payment_id" ~ '^pay_[A-Za-z0-9]{6,80}$' AND "workspace_refund_attempts"."state" IN ('prepared','processing','completed','failed','uncertain') AND ("workspace_refund_attempts"."provider_refund_id" IS NULL OR "workspace_refund_attempts"."provider_refund_id" ~ '^rfnd_[A-Za-z0-9]{6,80}$') AND ("workspace_refund_attempts"."evidence_hash" IS NULL OR "workspace_refund_attempts"."evidence_hash" ~ '^[a-f0-9]{64}$') AND ("workspace_refund_attempts"."state" <> 'completed' OR ("workspace_refund_attempts"."provider_refund_id" IS NOT NULL AND "workspace_refund_attempts"."evidence_hash" IS NOT NULL)));--> statement-breakpoint
ALTER TABLE "workspace_refund_completions" ADD CONSTRAINT "workspace_refund_completion_check" CHECK ("workspace_refund_completions"."amount_paise" > 0 AND "workspace_refund_completions"."currency" = 'INR' AND "workspace_refund_completions"."provider_mode" IN ('test','live') AND "workspace_refund_completions"."provider_refund_id" ~ '^rfnd_[A-Za-z0-9]{6,80}$' AND "workspace_refund_completions"."provider_payment_id" ~ '^pay_[A-Za-z0-9]{6,80}$' AND "workspace_refund_completions"."evidence_hash" ~ '^[a-f0-9]{64}$');
--> statement-breakpoint
-- Prospective Live fulfillment uses the same immutable paid-term/history guards.
CREATE OR REPLACE FUNCTION workspace_phase15b_membership_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE o workspace_membership_orders; p workspace_payment_attempts; c workspace_creator_profiles; expected_start timestamptz; expected_end timestamptz;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Membership terms and fulfillment history are immutable' USING ERRCODE='23514'; END IF;
 -- Serialize every initial fulfillment for the persisted owner. No extension or reset is necessary.
 PERFORM id FROM users WHERE id=NEW.user_id FOR UPDATE;
 SELECT * INTO o FROM workspace_membership_orders WHERE id=NEW.membership_order_id FOR UPDATE;
 SELECT * INTO c FROM workspace_creator_profiles WHERE id=NEW.creator_profile_id FOR UPDATE;
 SELECT * INTO p FROM workspace_payment_attempts WHERE membership_order_id=o.id AND provider_payment_id=o.winning_payment_id AND winner;
 IF o.id IS NULL OR c.id IS NULL OR c.user_id<>NEW.user_id OR c.status<>'enabled' OR o.user_id<>NEW.user_id
   OR o.activation_state<>'pending_activation' OR o.fulfilled_at IS NOT NULL OR o.review_reason IS NOT NULL OR o.financial_state<>'captured' OR o.provider_setup_state<>'ready'
   OR o.paid_at IS NULL OR o.refund_eligible_until IS DISTINCT FROM o.paid_at+interval '72 hours' OR o.paid_at<o.created_at OR o.paid_at>=o.eligibility_valid_until
   OR o.plan_version_id<>NEW.plan_version_id OR o.duration_months<>NEW.duration_months OR o.paid_at IS DISTINCT FROM NEW.paid_at
   OR o.launch_at IS DISTINCT FROM '2026-11-08T18:30:00.000Z'::timestamptz OR o.membership_start_rule_version<>'workspace-membership-start-v1'
   OR o.membership_start_rule IS DISTINCT FROM 'If payment is completed before 9 November 2026 at 00:00 IST, your paid membership term starts at launch. If payment is completed on or after launch, your membership starts on the successful payment date.'
   OR NOT ((o.provider_mode='test' AND o.commercial_policy_version='workspace-test-noncommercial-v1') OR (o.provider_mode='live' AND o.commercial_policy_version='workspace-live-commercial-v1'))
   OR (o.provider_mode='live' AND p.capture_time_source IS DISTINCT FROM 'razorpay_payment_captured_event_v1')
   OR p.id IS NULL OR p.state<>'captured' OR p.refunded_paise<>0 OR (p.capture_time_source IS NULL OR p.capture_time_source NOT IN ('test_authoritative','razorpay_payment_captured_event_v1'))
   OR (p.capture_time_source='razorpay_payment_captured_event_v1' AND NOT EXISTS (
     SELECT 1 FROM workspace_payment_events e WHERE e.provider_account_id=p.provider_account_id AND e.provider_mode=p.provider_mode
       AND e.event_type='payment.captured' AND e.anomaly_hash IS NULL
       AND e.evidence->>'providerOrderId'=p.provider_order_id AND e.evidence->>'providerPaymentId'=p.provider_payment_id
       AND (e.evidence->>'eventCreatedAt')::timestamptz=p.captured_at AND p.captured_at<=e.received_at))
   OR p.captured_at IS DISTINCT FROM o.paid_at OR p.provider_created_at>o.paid_at OR p.user_id<>o.user_id OR p.provider_order_id IS DISTINCT FROM o.provider_order_id
   OR p.provider_account_id<>o.provider_account_id OR p.provider_mode<>o.provider_mode OR p.amount_paise<>o.total_paise OR p.currency<>o.currency
   OR (o.coupon_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM workspace_coupon_redemptions WHERE membership_order_id=o.id AND user_id=o.user_id AND coupon_id=o.coupon_id AND status='redeemed')) THEN
   RAISE EXCEPTION 'Membership requires safe captured evidence and enabled matching creator' USING ERRCODE='23514';
 END IF;
 expected_start := greatest(o.paid_at, o.launch_at);
 expected_end := ((expected_start AT TIME ZONE 'Asia/Kolkata') + make_interval(months=>o.duration_months)) AT TIME ZONE 'Asia/Kolkata';
 IF NEW.starts_at IS DISTINCT FROM expected_start OR NEW.ends_at IS DISTINCT FROM expected_end OR
    EXISTS(SELECT 1 FROM workspace_memberships WHERE user_id=NEW.user_id AND (ends_at>NEW.fulfilled_at OR (starts_at<NEW.ends_at AND NEW.starts_at<ends_at))) THEN
   RAISE EXCEPTION 'Membership term mismatch or overlapping initial membership' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END; $$;
